from bisect import bisect_right

def timeLookup(ops):
    hist = {}
    out = []
    for typ, key, t, val in ops:
        if typ == 1:
            times, values = hist.setdefault(key, ([], []))
            times.append(t)
            values.append(val)
        else:
            if key not in hist:
                out.append(-1)
                continue
            times, values = hist[key]
            i = bisect_right(times, t) - 1
            out.append(values[i] if i >= 0 else -1)
    return out
